diff:
--- local66/workspace.css
+++ current/frontend/src/workspace.css
@@ -366,6 +366,29 @@
 .participation-actions .collection-card { display: flex; flex-direction: column; align-items: flex-start; }
 .participation-actions .collection-card > .button { margin-top: 16px; text-align: left; }
 @media (max-width: 600px) { .journey-mobile-checkpoints { display: block; } .journey-progress { margin-top: 24px; } }
+.patient-section-heading { gap: 12px 20px; flex-wrap: wrap; align-items: baseline; margin-bottom: 20px; }
+.patient-section-heading h2 { font-size: var(--text-title); line-height: 1.4; }
+.patient-section-heading > .muted { font-size: var(--text-caption); line-height: 1.5; }
+.count-circle { width: auto; min-width: 24px; height: 24px; padding: 0 6px; font-size: var(--text-caption); font-variant-numeric: tabular-nums; }
+.patient-surveys { gap: 16px; }
+.patient-survey-card { min-width: 0; padding: 24px; gap: 16px; transition: background-color 160ms ease, border-color 160ms ease; }
+.patient-survey-card > div { min-width: 0; }
+.patient-survey-card .badge { font-size: var(--text-caption); }
+.patient-survey-card h3 { font-size: 16px; line-height: 1.45; margin: 12px 0 8px; overflow-wrap: anywhere; }
+.patient-survey-card p { font-size: var(--text-body); line-height: 1.65; margin: 0 0 16px; text-wrap: pretty; }
+.patient-survey-card small { display: block; font-size: var(--text-caption); line-height: 1.6; }
+.survey-card-icon { width: 44px; height: 44px; border-radius: 10px; }
+.support-card { gap: 14px; padding: 20px; margin: 20px 0 24px; border: 1px solid var(--line); border-radius: 12px; }
+.support-card h3 { font-size: var(--text-body); line-height: 1.5; margin: 0 0 8px; }
+.support-card p { font-size: var(--text-label); line-height: 1.65; }
+.completed-survey > div { min-width: 0; }
+.completed-survey strong { font-size: var(--text-body); line-height: 1.5; overflow-wrap: anywhere; }
+.completed-survey small { font-size: var(--text-caption); line-height: 1.5; margin-top: 6px; }
+@media (max-width: 600px) {
+  .patient-survey-card { padding: 20px; gap: 12px; }
+  .patient-survey-card > .survey-card-icon { display: none; }
+  .support-card { padding: 18px; }
+}
 .patient-form { max-width: 820px; margin: 0 auto 24px; }
 .patient-form h1 { font-size: 26px; line-height: 1.35; margin: 20px 0 12px; color: var(--ink); }
 .patient-form .lede { font-size: 14px; color: var(--muted); line-height: 1.7; }
--- local66/brand-theme.css
+++ current/frontend/src/brand-theme.css
@@ -35,6 +35,18 @@
 .survey-tile.selected,.assign-patients .checkbox-label:has(:checked) { background:var(--signal-soft); border-color:var(--signal-dark); }
 .survey-tile strong { color:var(--ink); }
 .survey-tile:hover { border-color:var(--signal-dark); }
+.patient-section-heading h2,.patient-survey-card h3,.completed-survey strong,.support-card h3 { color:var(--ink); }
+.patient-survey-card p,.patient-survey-card small,.completed-survey small,.support-card,.support-card p { color:var(--muted); }
+.patient-survey-card,.completed-survey { border-color:var(--line); }
+.patient-survey-card:hover { background:var(--paper); border-color:var(--signal-dark); }
+.patient-survey-card > svg { color:var(--signal-dark); }
+.count-circle,.survey-card-icon { background:var(--signal-soft); color:var(--signal-dark); }
+.draft-disclosure { background:var(--paper); color:var(--muted); }
+.survey-question legend > .question-number { background:var(--signal-soft); color:var(--signal-dark); }
+.survey-question legend > .required-mark { color:var(--signal-dark); }
+.answer-option { color:var(--ink); }
+.answer-option:hover:not(:has(:disabled)) { background:var(--paper); border-color:var(--muted); }
+.answer-option.checked,.answer-option.checked:hover { background:var(--signal-soft); border-color:var(--signal-dark); color:var(--ink); }
 .workspace-start { background:var(--surface); border-color:var(--line); border-left:4px solid var(--signal); }
 .workspace-start-icon,.navigation-welcome > svg,.workspace-shortcut > svg { color:var(--signal-dark); border-color:var(--line); }
 .workspace-start p:not(.eyebrow),.navigation-welcome p,.workspace-path p,.workspace-shortcut small,.card-section-purpose { color:var(--muted); }
